import { ComponentPropsWithoutRef, ElementType, ReactNode } from 'react';

interface ContainerProps<T extends ElementType = 'div'> {
  as?: T;
  children: ReactNode;
}

function Container<T extends ElementType = 'div'>({ as, children, ...props }: ContainerProps<T> & ComponentPropsWithoutRef<T>) {
  const Component = as || 'div';
  return <Component {...props}>{children}</Component>;
}

// Usage
<Container>I'm a div</Container>
<Container as="span">I'm a span</Container>
<Container as="section" className="main">I'm a section</Container>

interface ButtonProps<T extends ElementType = 'button'> {
  as?: T;
  variant?: 'primary' | 'secondary';
  children: ReactNode;
}

function Button<T extends ElementType = 'button'>({ as, variant = 'primary', children, ...props }: ButtonProps<T> & ComponentPropsWithoutRef<T>) {
  const Component = as || 'button';
  return (
    <Component className={`btn-${variant}`} {...props}>
      {children}
    </Component>
  );
}

// Usage
<Button onClick={handleClick}>Click me</Button>
<Button as={Link} to="/home">Go home</Button>
<Button as="a" href="https://example.com">External link</Button>
